#include "fur_ribbon_geometry_candidate.h"
#include <iostream>
int main(){try{std::vector<FurSurfaceGuideCandidate>guides{{{0,0,0},{0,0,2}},{{10,0,0},{10,0,2}},{{0,0,0},{0,0,0}}};auto geometry=prepareFurRibbonsCandidate(guides,{0,-5,1},0.2f,0.25f);if(geometry.vertices.size()!=8||geometry.indices.size()!=12)throw std::runtime_error("ribbon counts");auto&a=geometry.vertices[0].position;auto&b=geometry.vertices[1].position;auto&c=geometry.vertices[2].position;auto&d=geometry.vertices[3].position;float rootWidth=std::sqrt((a[0]-b[0])*(a[0]-b[0])+(a[1]-b[1])*(a[1]-b[1]));float tipWidth=std::sqrt((c[0]-d[0])*(c[0]-d[0])+(c[1]-d[1])*(c[1]-d[1]));if(std::fabs(rootWidth-0.2f)>1e-6||std::fabs(tipWidth-0.05f)>1e-6)throw std::runtime_error("width/taper mismatch");for(uint32_t index:geometry.indices)if(index>=geometry.vertices.size())throw std::runtime_error("ribbon index range");auto parallel=prepareFurRibbonsCandidate({guides[0]},{0,0,5},0.2f,1);for(auto&v:parallel.vertices)for(float p:v.position)if(!std::isfinite(p))throw std::runtime_error("parallel view invalid");unsigned rejected=0;for(unsigned i=0;i<3;++i){try{prepareFurRibbonsCandidate(guides,{0,-5,1},i==0?0.f:0.2f,i==1?0.f:i==2?2.f:1.f);}catch(const std::runtime_error&){++rejected;}}if(rejected!=3)throw std::runtime_error("invalid ribbon accepted");std::cout<<"fur_ribbon_checks=4 invalid_rejections=3 zero_length_skipped parallel_view_finite width_taper_indices_valid renderer=unfinished\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
